661:     const spare = copies[copies.length - 1];
662:     dupes.push({group: g, item: spare, value: cardValue(g.card, spare.finish)});
663:   }
664:   const owned = new Set(state.items.map(i => i.cardId));
665:   const offeredIds = new Set();
666:   const usedDupes = new Set();
667:   for (let i = 0; i < 4 && dupes.length; i++) {
668:     const d = dupes[Math.floor(rnd() * dupes.length)];
669:     if (!d || usedDupes.has(d.item.uid)) continue;
670:     usedDupes.add(d.item.uid);
671:     const wantRank = RANK[d.group.card.rarity];
672:     const bump = rnd() > .8 ? 1 : 0;
673:     const targetRank = Math.min(4, wantRank + bump);
674:     const rarities = ['common','rare','epic','legendary','iconic'];
675:     let candidates = CARDS.filter(c => !owned.has(c.id) && !offeredIds.has(c.id) && RANK[c.rarity] === targetRank);
676:     if (!candidates.length) candidates = CARDS.filter(c => !owned.has(c.id) && !offeredIds.has(c.id) && Math.abs(RANK[c.rarity] - wantRank) <= 1);
