62:   const g = c.createGain();
63:   g.gain.setValueAtTime(0.0001, t0);
64:   g.gain.exponentialRampToValueAtTime(gain, t0 + .01);
65:   g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
66:   src.connect(f); f.connect(g); g.connect(master);
67:   src.start(t0); src.stop(t0 + dur + .05);
