90:     g.gain.exponentialRampToValueAtTime(gain * .35, t0 + dur * .6);
91:     g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
92:     osc.connect(f); f.connect(g); g.connect(master);
