654: export function tradeOffers() {
655:   const rnd = rngFrom(9001 + state.tradeSeed * 3517);
656:   const groups = groupedCollection().filter(g => g.count > 1);
657:   const offers = [];
658:   if (!groups.length) return offers;
659:   const dupes = [];
660:   for (const g of groups) {
661:     const copies = [...g.items].sort((a,b) => FINISH_ORDER.indexOf(a.finish) - FINISH_ORDER.indexOf(b.finish));
662:     const spare = copies[copies.length - 1];
663:     dupes.push({group: g, item: spare, value: cardValue(g.card, spare.finish)});
664:   }
665:   const owned = new Set(state.items.map(i => i.cardId));
666:   const offeredIds = new Set();
667:   const usedDupes = new Set();
668:   for (let i = 0; i < 4 && dupes.length; i++) {
669:     const d = dupes[Math.floor(rnd() * dupes.length)];
670:     if (!d || usedDupes.has(d.item.uid)) continue;
671:     usedDupes.add(d.item.uid);
672:     const wantRank = RANK[d.group.card.rarity];
673:     const bump = rnd() > .8 ? 1 : 0;
674:     const targetRank = Math.min(4, wantRank + bump);
675:     const rarities = ['common','rare','epic','legendary','iconic'];
676:     let candidates = CARDS.filter(c => !owned.has(c.id) && !offeredIds.has(c.id) && RANK[c.rarity] === targetRank);
677:     if (!candidates.length) candidates = CARDS.filter(c => !owned.has(c.id) && !offeredIds.has(c.id) && Math.abs(RANK[c.rarity] - wantRank) <= 1);
678:     if (!candidates.length) candidates = CARDS.filter(c => !owned.has(c.id) && !offeredIds.has(c.id));
679:     if (!candidates.length) break;
680:     const offerCard = candidates[Math.floor(rnd() * candidates.length)];
681:     offeredIds.add(offerCard.id);
682:     const offerValue = cardValue(offerCard, 'base');
683:     const ratio = offerValue / Math.max(1, d.value);
684:     offers.push({
685:       id: `t${state.tradeSeed}_${i}`,
686:       trader: TRADERS[(state.tradeSeed + i) % TRADERS.length],
687:       want: d.group.card,
688:       wantItem: d.item,
689:       wantFinish: d.item.finish,
690:       wantValue: d.value,
691:       give: offerCard,
692:       giveValue: offerValue,
693:       ratio,
694:       verdict: ratio >= 1.15 ? 'good' : ratio >= .82 ? 'fair' : 'bad',
695:     });
696:   }
697:   return offers;
698: }
