  background:radial-gradient(circle at 50% 35%, rgba(30,36,46,.96), rgba(6,8,12,.98) 70%);
  border:1.4px solid rgba(255,255,255,.35);box-shadow:0 3px 10px rgba(0,0,0,.6), inset 0 1px 1px rgba(255,255,255,.25), 0 0 0 2.5px rgba(0,0,0,.3);
  font-family:var(--font-display);line-height:.8}
