.pack-sport{margin-top:3cqw;font-family:var(--font-tech);font-weight:700;font-size:3.1cqw;letter-spacing:.3em;color:rgba(255,255,255,.85);display:flex;align-items:center;gap:1.5cqw}
.pack-sport::before{content:'';width:5cqw;height:2px;background:currentColor;opacity:.7}
.pack-title{margin-top:auto;position:relative;z-index:3;font-family:var(--font-display);font-weight:800;font-size:17cqw;line-height:.78;text-transform:uppercase;letter-spacing:-.01em;text-shadow:0 3px 12px rgba(0,0,0,.35)}
.pack-title small{display:block;font-size:4.6cqw;letter-spacing:.28em;font-weight:600;color:rgba(255,255,255,.75);margin-bottom:2cqw;font-family:var(--font-tech)}
.pack-bottom{margin-top:4cqw;position:relative;z-index:3;display:flex;align-items:flex-end;justify-content:space-between;gap:2cqw;border-top:1px solid rgba(255,255,255,.28);padding-top:3cqw}
.pack-meta{font-family:var(--font-tech);font-weight:600;font-size:2.4cqw;letter-spacing:.1em;text-transform:uppercase;color:rgba(255,255,255,.82);line-height:1.35}
.pack-meta b{display:block;font-size:3.4cqw;color:#fff;letter-spacing:.06em}
.pack-emblem{width:13cqw;height:13cqw;border-radius:50%;border:1.5px solid rgba(255,255,255,.45);display:grid;place-items:center;font-family:var(--font-display);font-weight:800;font-size:3.2cqw;letter-spacing:.05em;text-align:center;line-height:.9;color:#fff;background:rgba(0,0,0,.18);flex-shrink:0;box-shadow:inset 0 0 0 2px rgba(0,0,0,.12)}
