480: /* ---------- public ---------- */
481: export function cardArt(card, finish = 'base') {
482:   const id = ('art' + card.id + finish).replace(/[^a-z0-9]/gi, '').toLowerCase();
483:   const rnd = mulberry(hashStr(card.id + finish));
484:   const isPortrait = card.type === 'driver' || card.type === 'rider';
485:   let subject = '';
486:   if (isPortrait) subject = portrait(card, id, rnd);
487:   else if (card.type === 'team') subject = teamCrest(card, id);
488:   else if (card.type === 'car') subject = `<g transform="translate(0,8)">${carShape(id, card.colors, card.era, card.number)}</g>`;
489:   else if (card.type === 'bike') subject = `<g transform="translate(0,8)">${bikeShape(id, card.colors, card.number)}</g>`;
490:   else subject = momentScene(card, id, rnd);
491: 
492:   const parts = [
493:     defsFor(id, card),
494:     `<rect width="360" height="504" fill="#05060a"/>`,
495:     bgScene(card, id, finish),
496:     ghostText(card, id),
497:     subject,
498:     finish === 'gold' ? `<rect width="360" height="504" fill="url(#${id}-goldwash)" opacity=".18"/>` : '',
499:     `<rect width="360" height="504" fill="url(#${id}-vig)"/>`,
500:     `<rect y="300" width="360" height="204" fill="url(#${id}-fade)" opacity=".55"/>`,
501:   ];
502:   return `<svg viewBox="0 0 360 504" xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="xMidYMid slice" aria-hidden="true">${parts.join('')}</svg>`;
503: }
