/* ---------- driver / rider portrait ---------- */
function helmetPattern(style, id, a) {
  if (style === 0) return `<rect x="100" y="140" width="34" height="200" fill="${rgba(a,.85)}"/>`;
  if (style === 1) return `<g fill="${rgba(a,.75)}">${[...Array(5)].map((_,i)=>`<polygon points="${70+i*46},120 ${106+i*46},120 ${72+i*46},340 ${36+i*46},340"/>`).join('')}</g>`;
  if (style === 2) return `<g fill="none" stroke="${rgba(a,.8)}" stroke-width="11">${[...Array(3)].map((_,i)=>`<path d="M80 ${180+i*30}L160 ${150+i*30}L240 ${180+i*30}L320 ${150+i*30}"/>`).join('')}</g>`;
  if (style === 3) return `<rect x="220" y="120" width="120" height="220" fill="${rgba(a,.5)}"/><rect x="220" y="120" width="20" height="220" fill="${rgba('#fff',.25)}"/>`;
  return `<g fill="${rgba(a,.55)}">${[...Array(10)].map((_,i)=>`<circle cx="${110+(i%5)*34}" cy="${170+Math.floor(i/5)*44}" r="16"/>`).join('')}</g>`;
}

function portrait(card, id, rnd) {
