283: }
284: function weighted(entries, rnd = Math.random) {
285:   const total = entries.reduce((s,e) => s + e[1], 0);
286:   if (total <= 0) return entries[0]?.[0];
287:   let r = rnd() * total;
288:   for (const [key, w] of entries) { r -= w; if (r <= 0) return key; }
289:   return entries[entries.length-1][0];
290: }
291: function packPool(pack) {
292:   if (pack.scope === 'f1') return CARDS.filter(c => c.sport === 'f1');
293:   if (pack.scope === 'motogp') return CARDS.filter(c => c.sport === 'motogp');
294:   if (pack.scope === 'crossover') return CARDS;
295:   return CARDS.filter(c => c.sport !== 'crossover');
296: }
297: function rollRarity(pack, rnd) {
298:   return weighted(Object.entries(pack.odds).map(([k,v]) => [k, v]), rnd);
299: }
300: function cardOfRarity(pool, rarity, exclude, unownedOnly, owned, rnd) {
301:   let candidates = pool.filter(c => c.rarity === rarity && !exclude.has(c.id) && (!unownedOnly || !owned.has(c.id)));
302:   if (!candidates.length) {
303:     const order = ['common','rare','epic','legendary','iconic'];
304:     const start = order.indexOf(rarity);
305:     for (let d = 1; d < order.length && !candidates.length; d++) {
306:       for (const idx of [start-d, start+d]) {
307:         if (idx < 0 || idx >= order.length) continue;
308:         candidates = pool.filter(c => c.rarity === order[idx] && !exclude.has(c.id) && (!unownedOnly || !owned.has(c.id)));
309:         if (candidates.length) break;
310:       }
311:     }
312:   }
313:   if (!candidates.length) return null;
314:   return candidates[Math.floor(rnd() * candidates.length)];
315: }
316: function rollFinish(pack, card, rnd) {
317:   const weights = finishWeights(pack, card);
318:   const entries = Object.entries(weights).filter(([k,w]) => w > 0 && (k !== 'signature' || !!card.signature));
319:   return weighted(entries, rnd);
320: }
321: function serialFor(card) {
322:   const max = card.rarity === 'iconic' ? 25 : card.rarity === 'legendary' ? 50 : 99;
323:   return Math.floor(Math.random() * max) + 1;
324: }
