653: /* ---------------- trading ---------------- */
654: export function tradeOffers() {
655:   const rnd = rngFrom(9001 + state.tradeSeed * 3517);
656:   const groups = groupedCollection().filter(g => g.count > 1);
657:   const offers = [];
658:   if (!groups.length) return offers;
659:   const dupes = [];
660:   for (const g of groups) {
661:     // Keep the best finish; offer the lowest-value spare copy in a trade.
662:     const copies = [...g.items].sort((a,b) => FINISH_ORDER.indexOf(a.finish) - FINISH_ORDER.indexOf(b.finish));
663:     const spare = copies[0];
664:     dupes.push({group: g, item: spare, value: cardValue(g.card, spare.finish)});
665:   }
666:   const owned = new Set(state.items.map(i => i.cardId));
667:   const offeredIds = new Set();
668:   const usedDupes = new Set();
669:   for (let i = 0; i < 4 && dupes.length; i++) {
670:     const d = dupes[Math.floor(rnd() * dupes.length)];
671:     if (!d || usedDupes.has(d.item.uid)) continue;
672:     usedDupes.add(d.item.uid);
673:     const wantRank = RANK[d.group.card.rarity];
674:     const bump = rnd() > .8 ? 1 : 0;
675:     const targetRank = Math.min(4, wantRank + bump);
676:     const rarities = ['common','rare','epic','legendary','iconic'];
677:     let candidates = CARDS.filter(c => !owned.has(c.id) && !offeredIds.has(c.id) && RANK[c.rarity] === targetRank);
678:     if (!candidates.length) candidates = CARDS.filter(c => !owned.has(c.id) && !offeredIds.has(c.id) && Math.abs(RANK[c.rarity] - wantRank) <= 1);
679:     if (!candidates.length) candidates = CARDS.filter(c => !owned.has(c.id) && !offeredIds.has(c.id));
680:     if (!candidates.length) break;
681:     const offerCard = candidates[Math.floor(rnd() * candidates.length)];
682:     offeredIds.add(offerCard.id);
683:     const offerValue = cardValue(offerCard, 'base');
684:     const ratio = offerValue / Math.max(1, d.value);
685:     offers.push({
686:       id: `t${state.tradeSeed}_${i}`,
687:       trader: TRADERS[(state.tradeSeed + i) % TRADERS.length],
688:       want: d.group.card,
689:       wantItem: d.item,
690:       wantFinish: d.item.finish,
691:       wantValue: d.value,
692:       give: offerCard,
693:       giveValue: offerValue,
694:       ratio,
695:       verdict: ratio >= 1.15 ? 'good' : ratio >= .82 ? 'fair' : 'bad',
696:     });
697:   }
698:   return offers;
699: }
