496: export function cardArt(card, finish = 'base') {
497:   const id = ('art' + card.id + finish).replace(/[^a-z0-9]/gi, '').toLowerCase();
498:   const rnd = mulberry(hashStr(card.id + finish));
499:   const isPortrait = card.type === 'driver' || card.type === 'rider';
500:   let subject = '';
501:   if (isPortrait) subject = portrait(card, id, rnd);
502:   else if (card.type === 'team') subject = teamCrest(card, id);
503:   else if (card.type === 'car') subject = `<g>
504:     <ellipse cx="188" cy="326" rx="152" ry="46" fill="${rgba(card.colors[0],.24)}" filter="url(#${id}-soft)"/>
