76:   s.settings = {...base.settings, ...(raw.settings || {})};
77:   s.potd = {...base.potd, ...(raw.potd || {})};
78:   s.market = {...base.market, ...(raw.market || {})};
79:   s.items = Array.isArray(raw.items) ? raw.items.filter(it => it && CARD_MAP[it.cardId]) : [];
80:   s.tokens = Array.isArray(raw.tokens) ? raw.tokens.filter(t => PACK_MAP[t]) : [];
81:   s.claimedAchievements = Array.isArray(raw.claimedAchievements) ? raw.claimedAchievements : [];
82:   s.claimedAlbums = Array.isArray(raw.claimedAlbums) ? raw.claimedAlbums : [];
83:   s.dailyClaims = raw.dailyClaims && typeof raw.dailyClaims === 'object' ? raw.dailyClaims : {};
84:   s.recentPulls = Array.isArray(raw.recentPulls) ? raw.recentPulls.filter(p => CARD_MAP[p.cardId]).slice(0, 24) : [];
85:   s.coins = Math.max(0, Number(raw.coins) || 0);
86:   s.gems = Math.max(0, Number(raw.gems) || 0);
87:   s.level = Math.max(1, Number(raw.level) || 1);
88:   s.xp = Math.max(0, Number(raw.xp) || 0);
89:   if (!raw.starter) return seedStarter(s);
90:   ensureToday(s);
91:   return s;
92: }
