181: export function addItem(cardId, finish = 'base', opts = {}) {
182:   const card = CARD_MAP[cardId];
183:   if (!card) throw gameError('NO_CARD', 'Unknown card');
184:   const serial = finish === 'numbered' ? (opts.serial ?? Math.floor(Math.random() * (card.rarity === 'iconic' ? 25 : card.rarity === 'legendary' ? 50 : 99)) + 1) : null;
185:   const item = {uid: uid(), cardId, finish, serial, at: Date.now(), source: opts.source || 'pull'};
186:   state.items.push(item);
187:   const uniq = uniqueCount();
188:   if (uniq > state.stats.maxUnique) state.stats.maxUnique = uniq;
189:   return item;
190: }
191: export function uniqueCount() { return new Set(state.items.map(i => i.cardId)).size; }
192: export function cardCount(cardId) { return state.items.filter(i => i.cardId === cardId).length; }
193: export function ownsCard(cardId) { return state.items.some(i => i.cardId === cardId); }
194: export function itemsOfCard(cardId) { return state.items.filter(i => i.cardId === cardId); }
195: export function collectionValue() { return state.items.reduce((sum, i) => sum + cardValue(CARD_MAP[i.cardId], i.finish), 0); }
196: export function groupedCollection() {
197:   const map = new Map();
198:   for (const item of state.items) {
199:     if (!map.has(item.cardId)) {
200:       map.set(item.cardId, {card: CARD_MAP[item.cardId], items: [], count: 0, best: item.finish});
201:     }
202:     const g = map.get(item.cardId);
203:     g.items.push(item);
204:     g.count++;
205:     if (FINISH_ORDER.indexOf(item.finish) > FINISH_ORDER.indexOf(g.best)) g.best = item.finish;
206:   }
207:   return [...map.values()];
208: }
209: export function duplicateGroups() {
210:   return groupedCollection().filter(g => g.count > 1).map(g => ({
211:     ...g,
212:     spare: g.count - 1,
213:     value: cardValue(g.card, g.best),
214:   }));
215: }
216: export function sellItem(itemUid) {
217:   const idx = state.items.findIndex(i => i.uid === itemUid);
218:   if (idx < 0) throw gameError('NO_ITEM', 'Card not found');
219:   const item = state.items[idx];
220:   const card = CARD_MAP[item.cardId];
221:   const value = cardValue(card, item.finish);
222:   state.items.splice(idx, 1);
223:   state.coins += value;
224:   state.stats.cardsSold++;
225:   state.stats.coinsEarned += value;
226:   state.daily.cardsSold++;
227:   addXp(4);
228:   save(); emit();
229:   return {value, card, finish: item.finish};
230: }
231: export function sellAllDuplicates(filterFn = null) {
232:   const groups = groupedCollection();
233:   let total = 0, count = 0;
234:   const remove = [];
235:   for (const g of groups) {
236:     if (filterFn && !filterFn(g.card)) continue;
237:     if (g.items.length <= 1) continue;
238:     // keep the best copy, sell the rest
239:     const sorted = [...g.items].sort((a,b) => FINISH_ORDER.indexOf(b.finish) - FINISH_ORDER.indexOf(a.finish));
240:     for (const item of sorted.slice(1)) {
241:       total += cardValue(g.card, item.finish);
242:       count++;
243:       remove.push(item.uid);
244:     }
245:   }
246:   if (!count) return {count:0, total:0};
247:   state.items = state.items.filter(i => !remove.includes(i.uid));
248:   state.coins += total;
249:   state.stats.cardsSold += count;
250:   state.stats.coinsEarned += total;
251:   state.daily.cardsSold += count;
252:   addXp(count * 3);
253:   save(); emit();
254:   return {count, total};
255: }
256: export function sellAllCommons() {
257:   const groups = groupedCollection();
258:   let total = 0, count = 0;
259:   const remove = [];
260:   for (const g of groups) {
261:     if (g.card.rarity !== 'common') continue;
262:     if (g.items.length <= 1) continue;
263:     const sorted = [...g.items].sort((a,b) => FINISH_ORDER.indexOf(b.finish) - FINISH_ORDER.indexOf(a.finish));
264:     for (const item of sorted.slice(1)) {
265:       total += cardValue(g.card, item.finish); count++; remove.push(item.uid);
266:     }
267:   }
268:   if (!count) return {count:0, total:0};
269:   state.items = state.items.filter(i => !remove.includes(i.uid));
270:   state.coins += total;
271:   state.stats.cardsSold += count;
272:   state.stats.coinsEarned += total;
273:   state.daily.cardsSold += count;
274:   addXp(count * 2);
275:   save(); emit();
276:   return {count, total};
277: }
