657: export function tradeOffers() {
658:   const rnd = rngFrom(9001 + state.tradeSeed * 3517);
659:   const groups = groupedCollection().filter(g => g.count > 1);
660:   const offers = [];
661:   if (!groups.length) return offers;
662:   const dupes = [];
663:   for (const g of groups) {
664:     // Keep the best finish; offer the lowest-value spare copy in a trade.
665:     const copies = [...g.items].sort((a,b) => FINISH_ORDER.indexOf(a.finish) - FINISH_ORDER.indexOf(b.finish));
666:     const spare = copies[0];
667:     dupes.push({group: g, item: spare, value: cardValue(g.card, spare.finish)});
668:   }
669:   const owned = new Set(state.items.map(i => i.cardId));
670:   const offeredIds = new Set();
671:   const usedDupes = new Set();
672:   for (let i = 0; i < 4 && dupes.length; i++) {
673:     const d = dupes[Math.floor(rnd() * dupes.length)];
674:     if (!d || usedDupes.has(d.item.uid)) continue;
675:     usedDupes.add(d.item.uid);
676:     const wantRank = RANK[d.group.card.rarity];
677:     const bump = rnd() > .8 ? 1 : 0;
678:     const targetRank = Math.min(4, wantRank + bump);
679:     const rarities = ['common','rare','epic','legendary','iconic'];
680:     let candidates = CARDS.filter(c => !owned.has(c.id) && !offeredIds.has(c.id) && RANK[c.rarity] === targetRank);
681:     if (!candidates.length) candidates = CARDS.filter(c => !owned.has(c.id) && !offeredIds.has(c.id) && Math.abs(RANK[c.rarity] - wantRank) <= 1);
682:     if (!candidates.length) candidates = CARDS.filter(c => !owned.has(c.id) && !offeredIds.has(c.id));
683:     if (!candidates.length) break;
684:     const offerCard = candidates[Math.floor(rnd() * candidates.length)];
685:     offeredIds.add(offerCard.id);
686:     const offerValue = cardValue(offerCard, 'base');
687:     const ratio = offerValue / Math.max(1, d.value);
688:     offers.push({
689:       id: `t${state.tradeSeed}_${i}`,
690:       trader: TRADERS[(state.tradeSeed + i) % TRADERS.length],
691:       want: d.group.card,
692:       wantItem: d.item,
693:       wantFinish: d.item.finish,
694:       wantValue: d.value,
695:       give: offerCard,
696:       giveValue: offerValue,
697:       ratio,
698:       verdict: ratio >= 1.15 ? 'good' : ratio >= .82 ? 'fair' : 'bad',
699:     });
700:   }
701:   return offers;
702: }
