327: export function burst(color = '#ffc247', amount = 80, power = 1) {
328:   if (!fxCtx) return;
329:   const cx = innerWidth / 2, cy = innerHeight * 0.46;
330:   const palette = color === 'iconic'
331:     ? ['#ff66d8', '#ffe27a', '#65ffc8', '#5ad0ff', '#b17dff']
332:     : color === 'legendary'
333:       ? ['#ffc247', '#ffe8a8', '#ff9b30', '#ffffff']
334:       : [color, '#ffffff', '#ffd166'];
335:   for (let i = 0; i < amount; i++) {
336:     const ang = Math.random() * Math.PI * 2;
337:     const sp = (2.5 + Math.random() * 8) * power;
338:     particles.push({
339:       x: cx, y: cy,
340:       vx: Math.cos(ang) * sp,
341:       vy: Math.sin(ang) * sp - 2,
342:       size: 2 + Math.random() * 5,
343:       life: 1,
344:       decay: .008 + Math.random() * .012,
345:       color: palette[Math.floor(Math.random() * palette.length)],
346:       rot: Math.random() * 6,
347:       vr: (Math.random() - .5) * .3,
348:       shape: Math.random() > .55 ? 'line' : 'rect',
349:     });
350:   }
351:   if (!fxRaf) fxRaf = requestAnimationFrame(drawFx);
352: }
353: function drawFx() {
354:   if (!fxCtx) return;
355:   fxCtx.clearRect(0, 0, innerWidth, innerHeight);
356:   particles = particles.filter(p => p.life > 0);
357:   for (const p of particles) {
358:     p.x += p.vx; p.y += p.vy;
359:     p.vy += .13; p.vx *= .994; p.vy *= .994;
360:     p.life -= p.decay;
361:     p.rot += p.vr;
362:     fxCtx.save();
363:     fxCtx.globalAlpha = Math.max(0, p.life);
364:     fxCtx.fillStyle = p.color;
365:     fxCtx.translate(p.x, p.y);
366:     fxCtx.rotate(p.rot);
367:     if (p.shape === 'line') fxCtx.fillRect(-p.size * 2, -1, p.size * 4, 2);
368:     else fxCtx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size);
369:     fxCtx.restore();
370:   }
371:   if (particles.length) fxRaf = requestAnimationFrame(drawFx);
372:   else { fxRaf = 0; fxCtx.clearRect(0, 0, innerWidth, innerHeight); }
373: }
