.reveal-meta span{font-family:var(--font-tech);font-size:9.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted)}
.reveal-meta .new-pill{display:inline-flex;align-items:center;gap:5px;padding:2px 7px;border-radius:4px;background:rgba(62,224,138,.16);border:1px solid rgba(62,224,138,.35);color:var(--green);font-size:8.5px;letter-spacing:.13em;margin-top:2px}
.reveal-meta .dupe-pill{display:inline-flex;padding:2px 7px;border-radius:4px;background:rgba(255,255,255,.06);border:1px solid var(--line);color:var(--muted);font-size:8.5px;letter-spacing:.13em;margin-top:2px}
.reveal-actions{position:relative;z-index:5;display:flex;align-items:center;gap:10px;animation:metaUp .5s .4s both;flex-wrap:wrap;justify-content:center}
